import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"Duplicate Asset Detector Pro","description":"","frontmatter":{"sidebar_position":1},"headers":[],"relativePath":"duplicate-asset-detector/index.md","filePath":"duplicate-asset-detector/index.md","lastUpdated":1794045383000}'),s={name:"duplicate-asset-detector/index.md"};function r(n,e,o,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="duplicate-asset-detector-pro" tabindex="-1">Duplicate Asset Detector Pro <a class="header-anchor" href="#duplicate-asset-detector-pro" aria-label="Permalink to &quot;Duplicate Asset Detector Pro&quot;">​</a></h1><p>Duplicate Asset Detector Pro is a powerful editor tool that helps you find and clean up duplicate assets in your Unreal Engine projects. Save disk space, reduce build times, and keep your project organized with intelligent duplicate detection.</p><div class="info custom-block"><p class="custom-block-title">Actively Maintained</p><p>This plugin is actively maintained by Deblx. We provide bug fixes, Unreal Engine compatibility updates, and improvements as needed. See the <a href="https://changelog.deblx.com" target="_blank" rel="noreferrer">Deblx Changelog</a> for the latest releases.</p></div><h2 id="why-you-need-this-tool" tabindex="-1">Why You Need This Tool <a class="header-anchor" href="#why-you-need-this-tool" aria-label="Permalink to &quot;Why You Need This Tool&quot;">​</a></h2><p>Over time, Unreal projects accumulate duplicate assets - copied textures, materials, meshes, and more. These duplicates waste disk space, increase build times, and make your project harder to maintain. Our Plugin solves this problem with advanced content-based detection that finds true duplicates, not just similarly named files.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="smart-detection" tabindex="-1">Smart Detection <a class="header-anchor" href="#smart-detection" aria-label="Permalink to &quot;Smart Detection&quot;">​</a></h3><ul><li>Content-based hashing finds actual duplicates, not just similar names</li><li>Intelligent filtering excludes level actors, engine assets, and system files</li><li>Special handling for Materials, Textures, Static Meshes, and more</li></ul><h3 id="safe-cleanup" tabindex="-1">Safe Cleanup <a class="header-anchor" href="#safe-cleanup" aria-label="Permalink to &quot;Safe Cleanup&quot;">​</a></h3><ul><li>&quot;Redirect &amp; Delete&quot; safely removes duplicates while preserving all references</li><li>&quot;Delete Only&quot; for quick removal when you&#39;re sure</li><li>Preview before delete - see exactly what will be affected</li></ul><h3 id="flexible-scanning" tabindex="-1">Flexible Scanning <a class="header-anchor" href="#flexible-scanning" aria-label="Permalink to &quot;Flexible Scanning&quot;">​</a></h3><ul><li>Scan entire project or specific folders via right-click context menu</li><li>Filter by asset type, minimum file size, and custom paths</li><li>Exclude specific folders from scans</li><li>Include/exclude Engine and Plugin content</li></ul><h3 id="detailed-analysis" tabindex="-1">Detailed Analysis <a class="header-anchor" href="#detailed-analysis" aria-label="Permalink to &quot;Detailed Analysis&quot;">​</a></h3><ul><li>See file size, dependencies, and referencers for each asset</li><li>Visual thumbnails for quick identification</li><li>&quot;Wasted space&quot; calculation shows potential savings</li><li>Export reports to CSV, Excel, JSON and full report</li></ul><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h2><ul><li><strong>Supported Engine Versions:</strong> 5.1+</li><li><strong>Platforms:</strong> Windows, Mac, Linux</li><li><strong>Module Type:</strong> Editor Plugin</li><li><strong>Network Replicated:</strong> No</li><li><strong>Supported Asset Types:</strong> All (Textures, Materials, Static Meshes, Skeletal Meshes, Sounds, Blueprints, Data Tables, and more)</li></ul><h2 id="get-it-now" tabindex="-1">Get It Now <a class="header-anchor" href="#get-it-now" aria-label="Permalink to &quot;Get It Now&quot;">​</a></h2><p>Available on <a href="https://www.fab.com/de/sellers/Deblx" target="_blank" rel="noreferrer">Fab Marketplace</a></p>',18)])])}const f=a(s,[["render",r]]);export{p as __pageData,f as default};
